// 清洗事件数据
const events = $input.all();
return events.map(e => {
  const d = e.json;
  return {
    json: {
      userId: d.userId,
      eventType: d.eventType,
      timestamp: new Date(d.timestamp).toISOString(),
      properties: d.properties || {},
      sessionId: d.sessionId || Math.random().toString(36).slice(2),
      source: d.source || 'web'
    }
  };
});

// 漏斗计算逻辑
// 支持：page_view → add_to_cart → checkout → purchase
const FUNNEL_STEPS = ['page_view', 'add_to_cart', 'checkout', 'purchase'];

const events = $input.all().map(e => e.json);
const funnelCounts = {};

FUNNEL_STEPS.forEach(step => {
  funnelCounts[step] = new Set(
    events.filter(e => e.eventType === step).map(e => e.userId)
  ).size;
});

return [{
  json: {
    timestamp: new Date().toISOString(),
    funnelSteps: FUNNEL_STEPS,
    counts: funnelCounts,
    conversionRates: {
      step1to2: funnelCounts['page_view'] > 0 
        ? (funnelCounts['add_to_cart'] / funnelCounts['page_view'] * 100).toFixed(1) + '%' : 'N/A',
      step2to3: funnelCounts['add_to_cart'] > 0 
        ? (funnelCounts['checkout'] / funnelCounts['add_to_cart'] * 100).toFixed(1) + '%' : 'N/A',
      step3to4: funnelCounts['checkout'] > 0 
        ? (funnelCounts['purchase'] / funnelCounts['checkout'] * 100).toFixed(1) + '%' : 'N/A'
    }
  }
}];

